"""Server-rendered research studio dashboard."""

import html
from dataclasses import dataclass


@dataclass(slots=True)
class DashboardData:
    view: str
    connection: str
    expiry: str
    insights: list[dict]
    runs: list[dict]
    audiences: list[dict]
    drafts: list[dict]
    query: str = ""
    selection: str = ""
    status_filter: str = ""
    csrf: str = ""
    error: str = ""
    configured: bool = True
    threads_configured: bool = True


def _e(value) -> str:
    return html.escape(str(value if value is not None else ""), quote=True)


def _source(item: dict) -> str:
    url = str(item.get("source_url", ""))
    if url.startswith(("http://", "https://")):
        return f'<a class="source" href="{_e(url)}" target="_blank" rel="noreferrer">Open Threads source ↗</a>'
    return '<span class="muted">Source link unavailable</span>'


def _insight_card(item: dict, *, selectable: bool = False, selected: bool = False) -> str:
    checkbox = f'<label class="select"><input type="checkbox" name="insight_ids" value="{int(item["id"])}"{" checked" if selected else ""}> Use this evidence</label>' if selectable else ""
    return f'''<article class="evidence card" id="insight-{int(item["id"])}">
      <div class="card-top"><span class="tag">{_e(item["theme"])}</span><time>{_e(item.get("created_at", "")[:10])}</time></div>
      <blockquote>“{_e(item["quote"])}”</blockquote><p class="idea"><b>Product angle</b> · {_e(item["ebook_idea"])}</p>
      <div class="card-bottom">{_source(item)}{checkbox}</div>
    </article>'''


def _draft_content(draft: dict) -> str:
    content = draft["content"]
    if draft["kind"] == "threads_post":
        return f'<div class="draft-copy">{_e(content.get("post", ""))}</div>'
    if draft["kind"] == "ebook_outline":
        chapters = "".join(f'<li><b>{_e(ch.get("title", ""))}</b><span>{_e(ch.get("outcome", ""))}</span></li>' for ch in content.get("chapters", []) if isinstance(ch, dict))
        return f'<p><b>Premise:</b> {_e(content.get("premise", ""))}</p><p><b>Reader need:</b> {_e(content.get("intended_reader_need", ""))}</p><ol class="chapter-list">{chapters}</ol>'
    return f'<p><b>Concept:</b> {_e(content.get("concept", ""))}</p><p><b>Format:</b> {_e(content.get("format", ""))}</p><p><b>Visual direction:</b> {_e(content.get("visual_direction", ""))}</p><div class="draft-copy">{_e(content.get("copy", ""))}</div>'


def _draft_card(draft: dict, csrf: str = "") -> str:
    labels = {"threads_post": "Threads post", "ebook_outline": "eBook outline", "design_brief": "Design brief"}
    statuses = {"draft": "Needs review", "approved": "Approved", "archived": "Archived"}
    token = f'<input type="hidden" name="csrf" value="{_e(csrf)}">'
    source_ids = draft.get("source_ids", [])
    evidence = ", ".join(f'<a href="/?view=research&amp;q={int(i)}#insight-{int(i)}">#{int(i)}</a>' for i in source_ids if str(i).isdigit())
    actions = ""
    if draft["status"] != "approved":
        actions += f'<form method="post" action="/content/drafts/{int(draft["id"])}/status">{token}<input type="hidden" name="status" value="approved"><button class="button small">Approve for use</button></form>'
    if draft["status"] != "archived":
        actions += f'<form method="post" action="/content/drafts/{int(draft["id"])}/status">{token}<input type="hidden" name="status" value="archived"><button class="button ghost small">Archive</button></form>'
    actions += f'<button class="button ghost small" type="button" data-copy="draft-{int(draft["id"])}">Copy text</button>'
    return f'''<article class="draft card">
      <div class="card-top"><span class="tag">{_e(labels.get(draft["kind"], draft["kind"]))}</span><span class="status {draft["status"]}">{_e(statuses.get(draft["status"], draft["status"]))}</span></div>
      <h3>{_e(draft["title"])}</h3><div id="draft-{int(draft["id"])}" class="draft-body">{_draft_content(draft)}</div>
      <p class="muted small-copy">Grounded in insight {evidence or "—"} · {_e(draft.get("created_at", "")[:10])}</p>
      <div class="actions">{actions}</div>
    </article>'''


def render_dashboard(data: DashboardData, *, logout_action: str = "") -> str:
    view, connection, expiry = data.view, data.connection, data.expiry
    insights, runs, audiences, drafts = data.insights, data.runs, data.audiences, data.drafts
    query, error, configured = data.query, data.error, data.configured
    selection, status_filter = data.selection, data.status_filter
    csrf = data.csrf
    csrf_input = f'<input type="hidden" name="csrf" value="{_e(csrf)}">'
    threads_configured = data.threads_configured
    views = {"overview", "research", "audiences", "studio", "library", "settings"}
    view = view if view in views else "overview"
    labels = {"overview": "Overview", "research": "Research", "audiences": "Audiences", "studio": "Studio", "library": "Draft library", "settings": "Connections & settings"}
    nav = "".join(f'<a class="nav-link {"active" if view == key else ""}" href="/?view={key}"><span class="nav-mark"></span>{label}</a>' for key, label in labels.items())
    total_evidence = len(insights)
    latest = runs[0] if runs else None
    total_runs = len(runs)
    total_drafts = len(drafts)
    topic_text = " · ".join(latest["themes"][:4]) if latest else "No research run yet"
    status_class = "connected" if connection.startswith("Connected") else "disconnected"
    nav_error = f'<div class="notice error">{_e(error)}</div>' if error else ""
    error = ""
    notice = ""
    source_count = sum(item["evidence_count"] for item in audiences)
    latest_posts = latest.get("posts", []) if latest else []
    top_posts = sorted(latest_posts, key=lambda post: (post.get("engagement_score", 0), post.get("metrics", {}).get("views", 0)), reverse=True)[:5]
    post_rows = "".join(
        f'<tr><td><a class="source" href="{_e(p.get("permalink", ""))}" target="_blank" rel="noreferrer">{_e((p.get("text") or "Untitled")[:110])} ↗</a></td><td>{_e(p.get("metrics", {}).get("views", "—"))}</td><td>{_e(p.get("metrics", {}).get("likes", "—"))}</td><td>{_e(p.get("metrics", {}).get("replies", "—"))}</td><td>{_e(p.get("metrics", {}).get("reposts", "—"))}</td><td>{_e(p.get("engagement_score", 0))}</td></tr>'
        for p in top_posts if str(p.get("permalink", "")).startswith(("https://", "http://"))
    ) or '<tr><td colspan="6" class="muted">No post metrics saved yet. Run research to capture a bounded sample.</td></tr>'

    if view == "overview":
        run_note = f"Last run: {_e(latest['created_at'][:16].replace('T', ' '))} · {_e(latest['posts_sampled'])} posts sampled · {_e(latest['insights_count'])} evidence points" if latest else "Your first run will create a traceable research baseline."
        top_audiences = "".join(f'<a class="segment-row" href="/?view=audiences"><span>{_e(a["name"])}</span><b>{a["evidence_count"]}</b></a>' for a in audiences[:4]) or '<p class="muted">Run research to find recurring themes.</p>'
        latest_drafts = "".join(_draft_card(d, csrf) for d in drafts[:2]) or '<div class="empty">Turn a few saved insights into a post, ebook outline, or design brief.</div>'
        recent_evidence = "".join(_insight_card(item) for item in insights[:3]) or '<div class="empty">No evidence saved yet. Start with a bounded sample of the authorized Threads account.</div>'
        connect_link = '<a class="button" href="/auth/start">connect Threads →</a>' if not connection.startswith("Connected") else '<a class="text-link" href="/?view=settings">Manage connection →</a>'
        content = f'''<div class="welcome"><div><p class="eyebrow">PERPUSTAKAAN HATI · THREADS RESEARCH WORKSPACE</p><h1>From conversation<br>to something helpful.</h1><p class="lead">A careful path from Rahimam’s Threads sample to audience needs, grounded ideas, and reviewed content.</p></div><a class="button" href="/?view=research">Start with research <span>→</span></a></div>
          <div class="stats"><article class="stat card"><span>Evidence points</span><b>{total_evidence}</b><small>Saved, source-linked insights</small></article><article class="stat card"><span>Working segments</span><b>{len(audiences)}</b><small>Inferred from sampled language, not demographics</small></article><article class="stat card"><span>Drafts in library</span><b>{total_drafts}</b><small>Approval never auto-publishes</small></article><article class="stat card"><span>Research runs</span><b>{total_runs}</b><small>{run_note}</small></article></div>
          <div class="workflow card"><div class="section-head"><div><p class="eyebrow">YOUR WORKFLOW</p><h2>Evidence before ideas</h2></div><span class="step-count">4 steps</span></div><div class="steps"><a href="/?view=research"><i>01</i><b>Collect</b><small>Sample posts & public replies</small></a><span class="step-arrow">→</span><a href="/?view=audiences"><i>02</i><b>Understand</b><small>Group evidence by recurring need</small></a><span class="step-arrow">→</span><a href="/?view=studio"><i>03</i><b>Create</b><small>Draft posts, ebooks, design briefs</small></a><span class="step-arrow">→</span><a href="/?view=library"><i>04</i><b>Review</b><small>Approve, archive or copy</small></a></div></div>
          <div class="two-col"><section class="panel"><div class="section-head"><div><p class="eyebrow">AUDIENCE SIGNALS</p><h2>Emerging needs</h2></div><a class="text-link" href="/?view=audiences">All segments →</a></div>{top_audiences}</section><section class="panel"><div class="section-head"><div><p class="eyebrow">THREADS CONNECTION</p><h2>Research account</h2></div><span class="status {status_class}">{_e(connection)}</span></div><p class="muted">{_e(expiry) if expiry else "Connect the authorized Threads account to sample your own posts and visible replies."}</p>{connect_link}<p class="small-copy">{_e(topic_text)} · Sampled data from own-account research only.</p></section></div>
          <section class="panel"><div class="section-head"><div><p class="eyebrow">EVIDENCE · LATEST SAVED INSIGHTS</p><h2>Source-linked findings</h2></div><a class="text-link" href="/?view=research">Search all evidence →</a></div><div class="evidence-grid">{recent_evidence}</div></section>
          <section class="panel"><div class="section-head"><div><p class="eyebrow">POST PERFORMANCE · LATEST SAMPLE</p><h2>Top posts by engagement</h2></div><span class="tag">Owned posts only</span></div><div class="table-wrap"><table class="metrics"><thead><tr><th>Post</th><th>Views</th><th>Likes</th><th>Replies</th><th>Reposts</th><th>Engagement</th></tr></thead><tbody>{post_rows}</tbody></table></div></section>
          <section class="panel"><div class="section-head"><div><p class="eyebrow">RECENT WORK</p><h2>Drafts to review</h2></div><a class="text-link" href="/?view=library">Open library →</a></div><div class="draft-grid">{latest_drafts}</div></section>'''
    elif view == "research":
        selected_ids = {str(value) for value in selection.split(",") if value.isdigit()}
        cards = "".join(_insight_card(item, selectable=True, selected=str(item["id"]) in selected_ids) for item in insights) or '<div class="empty">No evidence saved yet. Connect Threads, then run the consented sample.</div>'
        history = "".join(f'<div class="run-row"><div><b>{_e(r["created_at"][:16].replace("T", " "))}</b><span>{_e(r["posts_sampled"])} sampled · {_e(r["selected_posts"])} prioritized · {_e(r["insights_count"])} insights</span></div><p>{_e(" · ".join(r["themes"][:3]) or "No recurring themes")}</p></div>' for r in runs) or '<p class="muted">Run history appears here after your first sample.</p>'
        content = f'''<div class="page-head"><div><p class="eyebrow">01 · COLLECT & INSPECT</p><h1>Research desk</h1><p class="lead">Sample your own recent Threads posts and visible public replies, then inspect every insight against its source.</p></div><span class="status {status_class}">{_e(connection)}</span></div>
        <div class="notice">{_e("Sample limits: at most 50 recent owned posts; top 5 by engagement; up to 50 visible direct replies per selected post. This is not all-time virality or public search.")}</div>
        <form class="run-bar card" method="post" action="/research/run">{csrf_input}<label class="consent"><input type="checkbox" name="consent" required><span>I understand that sampled posts and public replies will be sent to the configured AI provider for analysis.</span></label><button class="button" {"" if threads_configured and configured else "disabled"}>Run consented research <span>→</span></button></form>
        <section class="panel"><div class="section-head"><div><p class="eyebrow">EVIDENCE IN LIBRARY</p><h2>{total_evidence} saved insight{'' if total_evidence == 1 else 's'}</h2></div><form class="search" method="get"><input type="hidden" name="view" value="research"><input name="q" value="{_e(query)}" placeholder="Search themes, quotes, ideas"><button class="button ghost small">Search</button></form></div><form method="post" action="/content/generate">{csrf_input}<div class="evidence-grid">{cards}</div><div class="selection-bar"><label><input type="checkbox" name="consent" required> I consent to send selected saved insights to the configured AI provider to generate drafts.</label><button class="button" {"" if insights and configured else "disabled"}>Create grounded drafts <span>→</span></button></div></form></section>
        <section class="panel"><div class="section-head"><div><p class="eyebrow">RUN LOG</p><h2>Research history</h2></div></div>{history}</section>'''
    elif view == "audiences":
        audience_cards = "".join(f'''<article class="audience card"><div class="card-top"><span class="tag">WORKING SEGMENT</span><b class="count">{a["evidence_count"]}<small> signals</small></b></div><h2>{_e(a["name"])}</h2><p class="muted">{_e(a["basis"])}</p><div class="chips">{"".join(f'<span>{_e(t)}</span>' for t in a["themes"][:6])}</div><h3>Evidence</h3><div class="audience-evidence">{"".join(f'<blockquote>“{_e(e["quote"])}”<br>{_source(e)}</blockquote>' for e in a["evidence"][:3])}</div><h3>Potential product angles</h3><ul>{"".join(f'<li>{_e(x)}</li>' for x in a["ebook_angles"][:4]) or '<li>Collect more evidence before proposing a product.</li>'}</ul><a class="text-link" href="/?view=studio&amp;select={",".join(str(value) for value in a["source_ids"])}">Create content from this segment →</a></article>''' for a in audiences) or '<div class="empty">Audience segments appear when saved evidence is available. These are qualitative working hypotheses, not demographic claims.</div>'
        content = f'''<div class="page-head"><div><p class="eyebrow">02 · UNDERSTAND</p><h1>Audience signals</h1><p class="lead">Evidence-led working segments from sampled language. Each claim links back to source insights; no demographic inference is made.</p></div><div class="actions"><span class="tag">{source_count} evidence points</span><a class="button ghost small" href="/audiences/export.csv">Export evidence CSV</a></div></div><div class="audience-grid">{audience_cards}</div>'''
    elif view == "studio":
        selected = {value for value in selection.split(",") if value.isdigit()}
        options = "".join(f'<option value="{int(i["id"])}"{" selected" if str(i["id"]) in selected else ""}>#{int(i["id"])} · {_e(i["theme"])} — {_e(i["quote"][:90])}</option>' for i in insights)
        source_preview = "".join(_insight_card(i) for i in insights[:4]) or '<div class="empty">Run research before drafting so every idea can cite evidence.</div>'
        content = f'''<div class="page-head"><div><p class="eyebrow">03 · CREATE</p><h1>Content studio</h1><p class="lead">Choose research evidence; get a small, grounded set of content directions for a human to edit.</p></div><span class="tag">Draft only · no auto-publishing</span></div><div class="studio-layout"><form class="studio-form card" method="post" action="/content/generate">{csrf_input}<label class="field-label" for="source_ids">Evidence to use</label><input type="hidden" name="selected_ids" value="{_e(query)}"><select id="source_ids" name="insight_ids" multiple size="10" required>{options}</select><p class="help">Select multiple insights on desktop with Ctrl/Cmd-click. Segment-linked evidence is preselected. Drafts retain the chosen IDs as citations.</p><label class="consent"><input type="checkbox" name="consent" required><span>I consent to send selected saved insights to the configured AI provider to generate draft content.</span></label><button class="button" {"" if insights and configured else "disabled"}>Generate 3 reviewable ideas <span>→</span></button><p class="help">Outputs: one Threads post, one practical ebook chapter outline, one visual design brief.</p></form><section><h2 class="subhead">Available evidence</h2><div class="stack">{source_preview}</div></section></div>'''
    elif view == "library":
        draft_cards = "".join(_draft_card(d, csrf) for d in drafts) or '<div class="empty">No drafts yet. Select evidence in Research or open the Content Studio.</div>'
        content = f'''<div class="page-head"><div><p class="eyebrow">04 · REVIEW & REUSE</p><h1>Draft library</h1><p class="lead">Review, copy for manual use, approve as ready, or archive. “Approved” is not a publish action.</p></div><a class="button" href="/?view=studio">New evidence-led drafts →</a></div><div class="filter-pills"><a class="{"selected" if not status_filter else ""}" href="/?view=library">All</a><a class="{"selected" if status_filter == "draft" else ""}" href="/?view=library&amp;status=draft">Needs review</a><a class="{"selected" if status_filter == "approved" else ""}" href="/?view=library&amp;status=approved">Approved</a><a class="{"selected" if status_filter == "archived" else ""}" href="/?view=library&amp;status=archived">Archived</a></div><div class="draft-grid">{draft_cards}</div>'''
    else:
        content = f'''<div class="page-head"><div><p class="eyebrow">WORKSPACE SETTINGS</p><h1>Connections & settings</h1><p class="lead">Private data access, sample coverage, and AI provider setup.</p></div></div><div class="settings-grid"><article class="card settings-card"><p class="eyebrow">THREADS · OFFICIAL API</p><h2>{_e(connection)}</h2><p>{_e(expiry) if expiry else "Connect the authorized Threads profile used by this admin."}</p><p class="help">Reads this account’s own posts, engagement metrics, and visible direct replies. It does not search every public post or inspect other people’s reply engagement.</p><a class="button" href="/auth/start">{"Reconnect Threads" if connection.startswith("Connected") else "Connect Threads"}</a></article><article class="card settings-card"><p class="eyebrow">AI PROVIDER</p><h2>{"Ready for explicit-consent workflows" if configured else "API key not configured"}</h2><p>OpenRouter free routing only; request enforces a zero-cost provider limit. Research text is sent only after the separate consent checkbox is submitted.</p><p class="help">Set <code>OPENROUTER_API_KEY</code> in the server’s secret store. Never put it in browser code or paste it into chat.</p></article><article class="card settings-card"><p class="eyebrow">DATA & SAFETY</p><h2>Local research memory</h2><p>{total_evidence} evidence points · {total_runs} recorded runs · {total_drafts} drafts</p><p class="help">Sources remain clickable, quotes are evidence-checked, drafts retain source IDs. Approval means reviewed for use only; this admin does not publish or schedule posts.</p></article></div>'''

    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Threads research · {_e(labels[view])} · Perpustakaan Hati</title>
<style>
:root{{--bg:#f7f4ea;--paper:#fffdf6;--sage:#e9f0e6;--ink:#12251b;--muted:#59695d;--line:#d8d3c6;--gold:#7a5a22;--green:#256947;--deep:#153a29;--danger:#8a3833;--shadow:0 14px 40px -28px rgb(33 48 36/.28)}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}}a{{color:inherit}}button,input,select{{font:inherit}}.shell{{min-height:100vh;display:grid;grid-template-columns:250px minmax(0,1fr)}}aside{{position:sticky;top:0;height:100vh;padding:27px 18px;background:#12251b;color:#f7f4ea;display:flex;flex-direction:column;gap:24px}}.brand{{display:flex;align-items:center;gap:12px;padding:0 8px}}.brand-mark{{height:38px;width:38px;display:grid;place-items:center;border-radius:12px;background:#c9a86a;color:#12251b;font:bold 18px Georgia,serif}}.brand b{{display:block;font:600 15px Georgia,serif;letter-spacing:.02em}}.brand small{{display:block;color:#c8d2c9;font-size:11px;margin-top:2px}}.nav-label,.eyebrow{{font-size:10px;letter-spacing:.17em;font-weight:700;color:var(--gold);margin:0 0 8px}}aside .nav-label{{color:#a5b8aa;padding:0 12px}}nav{{display:grid;gap:5px}}.nav-link{{display:flex;align-items:center;gap:11px;padding:10px 12px;text-decoration:none;border-radius:9px;color:#dbe5dc;font-size:13px}}.nav-link:hover,.nav-link.active{{background:#294735;color:#fff}}.nav-link.active{{box-shadow:inset 3px 0 #d8bb7e}}.nav-mark{{height:7px;width:7px;border:1px solid #97b19d;border-radius:2px}}.nav-link.active .nav-mark{{background:#d8bb7e;border-color:#d8bb7e}}.side-bottom{{margin-top:auto;border-top:1px solid #385143;padding:15px 8px 0;color:#b8c8bb;font-size:12px}}.side-bottom a{{color:#f6e0b2}}.signout{{margin-top:12px;padding:0;border:0;background:transparent;color:#dbe5dc;font-size:12px;text-decoration:underline;cursor:pointer}}main{{min-width:0;max-width:1500px;width:100%;margin:auto;padding:34px clamp(20px,4vw,58px) 72px}}.topline{{display:flex;justify-content:space-between;align-items:center;margin-bottom:30px;color:var(--muted);font-size:12px}}.crumb{{font-weight:600;color:var(--ink)}}.account{{display:flex;align-items:center;gap:8px}}.dot{{width:8px;height:8px;border-radius:50%;background:#a2473a}}.dot.connected{{background:#3b8a5b}}h1,h2,h3,p{{margin-top:0}}h1{{font:500 clamp(34px,4vw,50px)/1.08 Georgia,serif;letter-spacing:-.025em;margin:0 0 12px}}h2{{font:500 23px/1.2 Georgia,serif;margin:0}}h3{{font:600 16px Georgia,serif;margin:16px 0 8px}}.lead{{max-width:700px;color:var(--muted);font-size:15px;margin:0}}.welcome,.page-head{{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:27px}}.welcome{{align-items:center;padding:22px 0 30px}}.welcome .eyebrow{{margin-bottom:12px}}.page-head .eyebrow{{margin-bottom:10px}}.button{{display:inline-flex;justify-content:center;align-items:center;gap:12px;border:0;border-radius:9px;background:var(--deep);color:white;text-decoration:none;font-weight:650;font-size:13px;padding:12px 16px;cursor:pointer;white-space:nowrap}}.button:hover{{background:#205239}}.button:disabled{{opacity:.45;cursor:not-allowed}}.button.ghost{{background:transparent;color:var(--deep);border:1px solid var(--line)}}.button.small{{padding:8px 11px;font-size:12px}}.card,.panel{{background:var(--paper);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow)}}.card{{padding:18px}}.stats{{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:18px}}.stat{{display:flex;flex-direction:column;gap:6px}}.stat>span{{color:var(--muted);font-size:12px}}.stat>b{{font:500 35px Georgia,serif}}.stat small{{color:var(--muted);font-size:11px;line-height:1.45}}.workflow,.panel{{padding:22px;margin:16px 0}}.section-head{{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:16px}}.section-head .eyebrow{{margin-bottom:6px}}.step-count,.tag{{display:inline-flex;align-items:center;border:1px solid #dfd4b9;border-radius:999px;padding:4px 9px;color:var(--gold);background:#faf6ea;font-size:10px;font-weight:700;letter-spacing:.07em}}.steps{{display:grid;grid-template-columns:1fr auto 1fr auto 1fr auto 1fr;align-items:center;gap:12px}}.steps>a{{display:grid;gap:4px;text-decoration:none;padding:12px 4px}}.steps i{{color:var(--gold);font:italic 14px Georgia,serif}}.steps b{{font:600 16px Georgia,serif}}.steps small{{font-size:11px;color:var(--muted)}}.step-arrow{{color:#b7a57c}}.two-col{{display:grid;grid-template-columns:1fr 1fr;gap:16px}}.panel{{box-shadow:none}}.panel .section-head{{margin-bottom:14px}}.text-link,.source{{font-size:12px;font-weight:650;color:var(--green);text-decoration:none}}.text-link:hover,.source:hover{{text-decoration:underline}}.segment-row{{display:flex;justify-content:space-between;padding:10px 0;border-top:1px solid #ebe7dc;text-decoration:none;font-size:13px}}.segment-row b{{color:var(--gold)}}.status{{font-size:11px;padding:5px 9px;border-radius:999px;background:#f4e9e6;color:var(--danger)}}.status.connected{{background:#e8f2e8;color:#276342}}.status.approved{{background:#e8f2e8;color:#276342}}.status.archived{{background:#efeee9;color:#6c706a}}.muted,.help{{color:var(--muted);font-size:12px}}.small-copy{{color:var(--muted);font-size:11px;margin:12px 0 0}}.table-wrap{{overflow-x:auto}}.metrics{{width:100%;border-collapse:collapse;font-size:12px;text-align:left}}.metrics th,.metrics td{{padding:10px 8px;border-top:1px solid #ece8df;white-space:nowrap}}.metrics th{{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.08em}}.metrics td:first-child{{max-width:460px;overflow:hidden;text-overflow:ellipsis}}.draft-grid,.audience-grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}}.audience-grid{{grid-template-columns:repeat(2,minmax(0,1fr))}}.draft{{min-width:0}}.card-top,.card-bottom{{display:flex;align-items:center;justify-content:space-between;gap:12px}}.card-top time{{color:var(--muted);font-size:10px}}.evidence blockquote{{font:500 17px/1.4 Georgia,serif;margin:14px 0;color:#24382b}}.idea{{font-size:12px;color:var(--muted)}}.card-bottom{{border-top:1px solid #eee9de;padding-top:11px;flex-wrap:wrap}}.select,.consent{{display:flex;align-items:flex-start;gap:9px;color:var(--muted);font-size:12px}}input[type=checkbox]{{accent-color:var(--green);margin-top:4px}}.page-head{{align-items:center}}.notice{{border:1px solid #e3d9c1;background:#fbf6e9;color:#61583f;border-radius:10px;padding:12px 15px;font-size:12px;margin:0 0 16px}}.notice.error{{background:#f9eae7;border-color:#e8c7c1;color:var(--danger)}}.run-bar{{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:16px}}.evidence-grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}}.selection-bar{{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid var(--line);padding-top:16px;margin-top:18px}}.search{{display:flex;gap:7px}}.search input,.studio-form select{{min-height:40px;border:1px solid var(--line);border-radius:8px;background:white;color:var(--ink);padding:8px 10px;min-width:230px}}.run-row{{display:grid;grid-template-columns:250px 1fr;gap:15px;padding:12px 0;border-top:1px solid #ece8df;font-size:12px}}.run-row div{{display:grid;gap:3px}}.run-row span,.run-row p{{color:var(--muted);margin:0}}.audience{{padding:21px}}.audience h2{{margin:13px 0 8px}}.audience .count{{font:500 23px Georgia,serif;color:var(--green)}}.audience .count small{{font:11px system-ui;color:var(--muted)}}.chips,.filter-pills{{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}}.chips span,.filter-pills a{{font-size:11px;color:var(--muted);background:var(--sage);padding:5px 9px;border-radius:999px;text-decoration:none}}.audience-evidence blockquote{{font:italic 14px Georgia,serif;border-left:2px solid #c9a86a;padding:2px 0 2px 11px;margin:9px 0}}.audience-evidence .source{{display:inline-block;margin-top:5px;font:600 11px system-ui}}.audience ul{{padding-left:18px;color:var(--muted);font-size:12px}}.studio-layout{{display:grid;grid-template-columns:minmax(300px,.8fr) minmax(0,1.2fr);gap:22px}}.studio-form{{height:max-content;display:grid;gap:12px}}.field-label{{font-weight:700;font-size:13px}}.studio-form select{{width:100%;height:260px;min-width:0}}.subhead{{font:500 22px Georgia,serif}}.stack{{display:grid;gap:10px}}.draft h3{{font-size:19px;margin:12px 0}}.draft-body{{font-size:13px;color:#34463a}}.draft-copy{{white-space:pre-wrap;background:#f5f3eb;border-radius:8px;padding:13px;font-size:14px}}.chapter-list{{padding-left:20px}}.chapter-list li{{padding:5px 0}}.chapter-list span{{display:block;color:var(--muted);font-size:12px}}.draft .actions{{display:flex;gap:7px;flex-wrap:wrap;margin-top:14px}}.draft .actions form{{margin:0}}.filter-pills a.selected{{background:var(--deep);color:white}}.settings-grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}}.settings-card h2{{font-size:20px;margin:8px 0}}.settings-card .button{{margin-top:12px}}.empty{{padding:25px;border:1px dashed #c9c6ba;border-radius:10px;color:var(--muted);font-size:13px;text-align:center;grid-column:1/-1}}.mobile-brand{{display:none}}
@media(max-width:950px){{.shell{{grid-template-columns:205px minmax(0,1fr)}}aside{{padding-inline:12px}}main{{padding-inline:25px}}.stats{{grid-template-columns:repeat(2,minmax(0,1fr))}}.steps{{grid-template-columns:1fr 1fr;gap:5px}}.step-arrow{{display:none}}.steps>a{{border:1px solid #eee9de;border-radius:9px;padding:10px}}.two-col{{grid-template-columns:1fr}}}}
@media(max-width:680px){{.shell{{display:block;padding-bottom:64px}}aside{{position:fixed;z-index:10;top:auto;bottom:0;width:100%;height:auto;padding:7px 8px calc(7px + env(safe-area-inset-bottom));display:block;border-top:1px solid #49614f}}.brand,.nav-label{{display:none}}.side-bottom{{margin:0;padding:0;border:0;display:block;position:fixed;right:12px;bottom:70px;background:#12251b;border-radius:10px;padding:10px 14px;box-shadow:0 8px 28px rgb(0 0 0/.22)}}.side-bottom>a{{display:none}}nav{{display:flex;justify-content:space-around;gap:2px}}.nav-link{{flex:1;justify-content:center;flex-direction:column;gap:3px;padding:6px 2px;font-size:9px}}.nav-mark{{height:6px;width:6px}}main{{padding:19px 15px 36px}}.topline{{margin-bottom:20px}}.welcome,.page-head{{display:block}}.welcome .button,.page-head>.button{{margin-top:17px}}.welcome{{padding:14px 0 22px}}h1{{font-size:37px}}.stats{{gap:8px}}.stat{{padding:13px}}.stat>b{{font-size:28px}}.stat small{{font-size:10px}}.workflow,.panel{{padding:16px;margin:12px 0}}.steps{{gap:6px}}.steps b{{font-size:14px}}.steps small{{font-size:10px}}.draft-grid,.audience-grid,.evidence-grid,.settings-grid,.studio-layout{{grid-template-columns:1fr}}.run-bar,.selection-bar{{align-items:stretch;flex-direction:column}}.run-bar .button,.selection-bar .button{{width:100%}}.section-head{{align-items:flex-start;flex-direction:column}}.search{{width:100%}}.search input{{min-width:0;flex:1}}.run-row{{grid-template-columns:1fr;gap:5px}}.status{{display:inline-flex;margin-top:5px}}.filter-pills{{gap:5px}}}}
</style></head><body><div class="shell"><aside><div class="brand"><div class="brand-mark">PH</div><div><b>Perpustakaan Hati</b><small>Research studio</small></div></div><div><p class="nav-label">WORKSPACE</p><nav>{nav}</nav></div><div class="side-bottom">Research is a sample, not a census.<br><a href="/?view=settings">Privacy & connections →</a>{logout_action}</div></aside><main><div class="topline"><span class="crumb">Workspace <span class="muted">/</span> { _e(labels[view]) }</span><span class="account"><i class="dot {status_class}"></i> Rahimam’s Threads account</span></div>{notice}{nav_error}{content}</main></div>
<script>document.addEventListener('click',async e=>{{const b=e.target.closest('[data-copy]');if(!b)return;const el=document.getElementById(b.dataset.copy);if(!el)return;const text=el.innerText;try{{await navigator.clipboard.writeText(text);b.textContent='Copied';setTimeout(()=>b.textContent='Copy text',1400)}}catch{{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();b.textContent='Copied'}}}});</script></body></html>'''
